-- ============================================
-- LUMA — Thème 5 (Santé) : 3 scénarios COURTS x4
-- ============================================


update scenarios set content = '{"characters": {"doctor": "le médecin"}, "start_node": "n1", "nodes": {"n1": {"speaker": "doctor", "text": "Good morning, what brings you in today?", "text_fr": "Bonjour, qu''est-ce qui vous amène aujourd''hui ?", "choices": [{"text": "I''ve had a sore throat and a fever since yesterday.", "text_fr": "J''ai mal à la gorge et de la fièvre depuis hier.", "next": "n2"}, {"text": "I haven''t been feeling well for a couple of days.", "text_fr": "Je ne me sens pas bien depuis quelques jours.", "next": "n2b"}]}, "n2": {"speaker": "doctor", "text": "I see. How high has the fever been?", "text_fr": "Je vois. La fièvre est montée à combien ?", "choices": [{"text": "About 38.5 degrees, I checked this morning.", "text_fr": "Environ 38,5 degrés, j''ai vérifié ce matin.", "next": "n3"}, {"text": "I''m not sure exactly, but I feel quite warm.", "text_fr": "Je ne suis pas sûr exactement, mais je me sens assez chaud.", "next": "n3"}]}, "n2b": {"speaker": "doctor", "text": "Can you describe your symptoms a bit more?", "text_fr": "Vous pouvez décrire vos symptômes un peu plus ?", "choices": [{"text": "Sore throat, mild fever, and I''m quite tired.", "text_fr": "Mal de gorge, fièvre légère, et je suis assez fatigué.", "next": "n3"}]}, "n3": {"speaker": "doctor", "text": "Let me take a look at your throat. Open wide, please.", "text_fr": "Laissez-moi regarder votre gorge. Ouvrez grand, s''il vous plaît.", "choices": [{"text": "(Open your mouth for the examination.)", "text_fr": "(Ouvre la bouche pour l''examen.)", "next": "n4"}]}, "n3b": {"speaker": "doctor", "text": "Any other symptoms, like coughing or body aches?", "text_fr": "D''autres symptômes, comme de la toux ou des courbatures ?", "choices": [{"text": "A little cough, and my body does ache a bit.", "text_fr": "Un peu de toux, et mon corps me fait un peu mal.", "next": "n4"}]}, "n4": {"speaker": "doctor", "text": "It looks a bit red and inflamed — likely a viral infection.", "text_fr": "Ça semble un peu rouge et enflammé — probablement une infection virale.", "choices": [{"text": "Is there anything I should take for it?", "text_fr": "Y a-t-il quelque chose que je devrais prendre pour ça ?", "next": "n5"}, {"text": "How long should I expect this to last?", "text_fr": "Combien de temps ça devrait durer ?", "next": "n5b"}]}, "n5": {"speaker": "doctor", "text": "Rest, fluids, and over-the-counter pain relief should help. No antibiotics needed.", "text_fr": "Repos, hydratation, et un antidouleur en vente libre devraient aider. Pas besoin d''antibiotiques.", "choices": [{"text": "Thank you, I''ll follow that advice.", "text_fr": "Merci, je vais suivre ces conseils.", "next": "end_advised"}]}, "n5b": {"speaker": "doctor", "text": "Usually about five to seven days with rest and fluids.", "text_fr": "Généralement cinq à sept jours avec repos et hydratation.", "choices": [{"text": "Understood, thank you for the explanation.", "text_fr": "Compris, merci pour l''explication.", "next": "end_advised"}]}, "end_advised": {"speaker": "doctor", "text": "Come back if it doesn''t improve within a week. Take care!", "text_fr": "Revenez si ça ne s''améliore pas d''ici une semaine. Prenez soin de vous !", "end": true, "ending_label": "Consultation claire et rassurante 🩺"}}}'::jsonb, is_playable = true
where title = 'Décrire un symptôme simple à un médecin'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));


update scenarios set content = '{"characters": {"stranger": "un passant", "you": "vous", "you_thought": "narration"}, "start_node": "n1b", "nodes": {"n1": {"speaker": "stranger", "text": "Excuse me, do you know your way around here?", "text_fr": "Excusez-moi, vous connaissez bien le coin ?", "choices": [{"text": "A little — are you looking for something?", "text_fr": "Un peu — vous cherchez quelque chose ?", "next": "n2"}]}, "n1b": {"speaker": "you_start", "text": "(You approach a stranger on the street to ask for directions.)", "text_fr": "(Vous approchez un inconnu dans la rue pour demander votre chemin.)", "choices": [{"text": "Excuse me, is there a pharmacy nearby?", "text_fr": "Excusez-moi, il y a une pharmacie à proximité ?", "next": "n2b"}]}, "n2": {"speaker": "you", "text": "Yes, actually — is there a pharmacy nearby? I need something for a headache.", "text_fr": "Oui, en fait — il y a une pharmacie à proximité ? J''ai besoin de quelque chose pour un mal de tête.", "choices": [{"text": "(Wait for their response.)", "text_fr": "(Attends leur réponse.)", "next": "n3"}]}, "n2b": {"speaker": "stranger", "text": "Yes, there''s one just two blocks from here, on the left.", "text_fr": "Oui, il y en a une juste à deux rues d''ici, sur la gauche.", "choices": [{"text": "Great, thank you! Is it easy to spot?", "text_fr": "Super, merci ! C''est facile à repérer ?", "next": "n3b"}]}, "n3": {"speaker": "stranger", "text": "Sure, there''s one two blocks down, past the bakery.", "text_fr": "Bien sûr, il y en a une deux rues plus loin, après la boulangerie.", "choices": [{"text": "Perfect, thank you so much for your help.", "text_fr": "Parfait, merci beaucoup pour votre aide.", "next": "n4"}]}, "n3b": {"speaker": "stranger", "text": "Yes, it has a big green cross sign, hard to miss.", "text_fr": "Oui, il y a une grande croix verte, difficile à rater.", "choices": [{"text": "Perfect, thank you very much!", "text_fr": "Parfait, merci beaucoup !", "next": "n4"}]}, "n4": {"speaker": "stranger", "text": "You''re welcome, I hope you feel better soon!", "text_fr": "Je vous en prie, j''espère que vous irez mieux bientôt !", "choices": [{"text": "Thank you, have a great day!", "text_fr": "Merci, bonne journée !", "next": "end_found"}]}, "end_found": {"speaker": "you_thought", "text": "(You find the pharmacy easily and get what you need.)", "text_fr": "(Vous trouvez la pharmacie facilement et obtenez ce dont vous avez besoin.)", "end": true, "ending_label": "Pharmacie trouvée sans souci 💊"}}}'::jsonb, is_playable = true
where title = 'Demander une pharmacie'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));
